using Payments;

namespace PaymentGateway.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private readonly Payments.PaymentGateway _gateway;

    public PaymentGatewayTests()
    {
        _gateway = new Payments.PaymentGateway();
    }

    #region ChargeAsync Tests

    [TestMethod]
    public async Task ChargeAsync_ValidCardAndAmount_ReturnsSuccessResult()
    {
        // Arrange
        var cardToken = "tok_valid_visa";
        var amount = 50.00m;

        // Act
        var result = await _gateway.ChargeAsync(cardToken, amount);

        // Assert
        Assert.IsNotNull(result);
        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.ChargeId);
    }

    [TestMethod]
    public async Task ChargeAsync_ValidCard_ReturnsNonEmptyChargeId()
    {
        // Arrange
        var cardToken = "tok_valid_visa";
        var amount = 25.00m;

        // Act
        var result = await _gateway.ChargeAsync(cardToken, amount);

        // Assert
        Assert.IsNotNull(result.ChargeId);
        Assert.AreNotEqual(string.Empty, result.ChargeId);
    }

    [TestMethod]
    [DataRow("")]
    [DataRow(null)]
    public async Task ChargeAsync_NullOrEmptyCardToken_ThrowsArgumentException(string? cardToken)
    {
        // Act & Assert
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(cardToken!, 10.00m));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    [DataRow(-100.50)]
    public async Task ChargeAsync_ZeroOrNegativeAmount_ThrowsArgumentOutOfRangeException(double amount)
    {
        // Act & Assert
        await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_valid", (decimal)amount));
    }

    [TestMethod]
    [DataRow(0.01)]
    [DataRow(99.99)]
    [DataRow(1000.00)]
    public async Task ChargeAsync_VariousValidAmounts_Succeeds(double amount)
    {
        // Act
        var result = await _gateway.ChargeAsync("tok_valid_visa", (decimal)amount);

        // Assert
        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_DeclinedCard_ReturnsFailureResult()
    {
        // Arrange
        var cardToken = "tok_declined";

        // Act
        var result = await _gateway.ChargeAsync(cardToken, 50.00m);

        // Assert
        Assert.IsNotNull(result);
        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_MultipleCalls_ReturnUniqueChargeIds()
    {
        // Act
        var result1 = await _gateway.ChargeAsync("tok_valid_visa", 10.00m);
        var result2 = await _gateway.ChargeAsync("tok_valid_visa", 20.00m);

        // Assert
        Assert.AreNotEqual(result1.ChargeId, result2.ChargeId);
    }

    #endregion

    #region RefundAsync Tests

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccessResult()
    {
        // Arrange — charge first, then refund
        var charge = await _gateway.ChargeAsync("tok_valid_visa", 75.00m);

        // Act
        var result = await _gateway.RefundAsync(charge.ChargeId);

        // Assert
        Assert.IsNotNull(result);
        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.RefundId);
    }

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsNonEmptyRefundId()
    {
        // Arrange
        var charge = await _gateway.ChargeAsync("tok_valid_visa", 30.00m);

        // Act
        var result = await _gateway.RefundAsync(charge.ChargeId);

        // Assert
        Assert.IsNotNull(result.RefundId);
        Assert.AreNotEqual(string.Empty, result.RefundId);
    }

    [TestMethod]
    [DataRow("")]
    [DataRow(null)]
    public async Task RefundAsync_NullOrEmptyChargeId_ThrowsArgumentException(string? chargeId)
    {
        // Act & Assert
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(chargeId!));
    }

    [TestMethod]
    public async Task RefundAsync_NonExistentChargeId_ReturnsFailureResult()
    {
        // Act
        var result = await _gateway.RefundAsync("ch_nonexistent_12345");

        // Assert
        Assert.IsFalse(result.Success);
    }

    #endregion
}

